        /// The Dex Id (see DEXId enum for interpretation)
        uint8 dexId;
        /// Bonding-curve fee rate in bps for non-tax TOKEN_V3_PERMIT tokens (e.g. 125 = 1.25%). 0 otherwise.
        uint16 bondingCurveFeeRate;
    }

    /// @notice Parameters for creating a new token (V2)
    struct NewTokenV2Params {
