        uint8 dexId; // DEX ID for MultiDexRouter dispatch
        uint24 fee; // fee tier in pips (V2 = 0)
        int24 tickSpacing; // tick spacing for V4 / PCS_INFINITY_CL; 0 for V2 / V3
        address tokenOut; // output token of this hop (== quoteToken on the final hop)
